import json
with open('.vf-claude/d326064c9bf745b9ba297c977be17403/projects/-app/500c7c2c-c6da-4492-9b97-1065fa9a1107.jsonl', 'r') as f:
    for i, line in enumerate(f):
        data = json.loads(line)
        msg = data.get('message', {})
        role = msg.get('role')
        content = msg.get('content')
        if role == 'assistant':
            print(f'=== Assistant turn at line {i} ===')
            if isinstance(content, list):
                for item in content:
                    if item.get('type') == 'text':
                        print('TEXT:', item.get('text')[:300])
                    elif item.get('type') == 'tool_use':
                        print('TOOL:', item.get('name'), item.get('input'))
            elif isinstance(content, str):
                print('TEXT STR:', content[:300])
